import ast
import importlib.util
import json
from pathlib import Path

partition = json.loads(Path('docs/deployment/evidence/BFF-TEST-MIGRATION-REPARTITION-PLAN-001/partition.json').read_text())
child = next(c for c in partition['candidate_children'] if c['task_id'] == 'BFF-TEST-MIGRATION-B14-LOOPS-PAPER-V5-001')
files = child['source_artifacts']
all_files = [f for c in partition['candidate_children'] for f in c['source_artifacts']]
assert len(files) == 11 and len(all_files) == len(set(all_files)) == 184
results = []
for path in files:
    tree = ast.parse(Path(path).read_text(), filename=path)
    hits = {'ast_imports': [], 'dynamic_imports': [], 'subprocess_main_references': [], 'sys_path_mutations': []}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name in ('main', 'services.control_plane.bff.main'):
                    hits['ast_imports'].append({'line': node.lineno, 'module': alias.name})
        elif isinstance(node, ast.ImportFrom):
            if node.module in ('main', 'services.control_plane.bff.main') or (node.module == 'services.control_plane.bff' and any(a.name == 'main' for a in node.names)):
                hits['ast_imports'].append({'line': node.lineno, 'module': node.module})
        elif isinstance(node, ast.Call):
            name = ast.unparse(node.func)
            literals = [n.value for n in ast.walk(node) if isinstance(n, ast.Constant) and isinstance(n.value, str)]
            if name.endswith('import_module') or name == '__import__':
                if any(s in ('main', 'services.control_plane.bff.main') for s in literals):
                    hits['dynamic_imports'].append(node.lineno)
            if name.startswith('subprocess.') and any('main.py' in s or 'import main' in s for s in literals):
                hits['subprocess_main_references'].append(node.lineno)
            if name in ('sys.path.insert', 'sys.path.append', 'sys.path.remove'):
                hits['sys_path_mutations'].append(node.lineno)
    assert hits['ast_imports'], path
    results.append({'path': path, 'disposition': 'blocked_unmigrated', **hits})
main_tree = ast.parse(Path('services/control-plane/bff/main.py').read_text())
names = {'_build_persona_health_items', '_trading_performance_delta', '_overlay_source_health_truth'}
definitions = {n.name: {'path': 'services/control-plane/bff/main.py', 'line': n.lineno} for n in main_tree.body if isinstance(n, ast.FunctionDef) and n.name in names}
assert set(definitions) == names
spec = importlib.util.spec_from_file_location('b14_runtime_service_probe', 'services/control-plane/bff/runtime/service.py')
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
try:
    module.RuntimeRouterService().dependency('_build_persona_health_items')('2026-07-26T00:00:00Z', include_market_persona_defaults=True)
except RuntimeError as exc:
    missing_dependency = str(exc)
    assert 'was not supplied' in missing_dependency
else:
    raise AssertionError('Expected the missing runtime projection dependency to fail closed')
print(json.dumps({'partition': {'b14_files': 11, 'total_files': 184, 'pairwise_disjoint': True}, 'importer_count': len(results), 'importers': results, 'main_owned_definitions': definitions, 'runtime_seam_probe': {'expected_missing_dependency_confirmed': True, 'message': missing_dependency}}, indent=2))
